pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor, uint256 callerIdx) public {
        // Keep amounts in a wide admissible range
        amount1 = bound(amount1, 1, type(uint128).max);
        amount2 = bound(amount2, 1, type(uint128).max);
        // Use a distinct adversarial callee that always reverts on receive
        Reverter reverter = new Reverter();
        address callee = callerIdx % 2 == 0 ? actor : address(reverter);
        vm.assume(actor != address(0) && actor.code.length == 0);
        vm.assume(callee != address(reverter) || uint256(uint160(actor)) > 1); // keep fuzz diversity

        // First deposit: give actor ether and deposit into c
        vm.deal(address(actor), amount1);
        vm.prank(actor);
        c.deposit{value: amount1}();

        // Record state before withdraw
        uint256 balanceBefore = address(c).balance;

        // Second, if we are to trigger adversarial case, let the reverter have some credit by depositing from actor
        if (callee == address(reverter)) {
            // Give reverter some ether and deposit
            vm.deal(address(reverter), amount2);
            vm.prank(address(reverter));
            c.deposit{value: amount2}();
            // Now withdraw as reverter; reverter's receive reverts
            vm.prank(address(reverter));
        } else {
            // Normal actor withdraw
            vm.prank(actor);
            c.deposit{value: amount2}(); // extra deposit for actor
            vm.prank(actor);
        }

        bool callSuccess;
        try c.withdrawAll() {
            callSuccess = true;
        } catch {
            callSuccess = false;
        }

        uint256 balanceAfter = address(c).balance;

        // Universal invariant: if withdrawAll reverts, then ETH balance must be unchanged.
        // The bug breaks this when a failing call is made to reverter: the transfer fails but
        // state is still updated, reducing balance and zeroing credit without returning ether.
        assertTrue(!callSuccess ? balanceAfter == balanceBefore : true);
    }
}

