pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 nonce) public {
        // Bound deposit to avoid overflow in credit (type(uint256).max)
        depositAmt = bound(depositAmt, 1, type(uint128).max);

        // Deploy a reverter helper — a contract whose receive reverts
        Reverter attacker = new Reverter();
        address reverterAddr = address(attacker);

        // Fund the reverter and deposit into c on its behalf
        vm.deal(reverterAddr, depositAmt);
        vm.prank(reverterAddr);
        c.deposit{value: depositAmt}();

        // Record state before withdrawal
        uint256 creditBefore = c.credit(reverterAddr);
        uint256 balanceBefore = address(c).balance;

        // Attempt withdrawal from the reverter; the reverter's receive will revert
        bool reverted;
        vm.prank(reverterAddr);
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The invariant: if the call to withdrawAll reverts, credit and balance MUST be unchanged.
        // Reference: always reverts → credit unchanged, ETH unchanged.
        // Bug: does not revert, zeroes credit, reduces ETH.
        assertTrue(
            reverted
                ? (c.credit(reverterAddr) == creditBefore && address(c).balance == balanceBefore)
                : true // if it doesn't revert, the invariant is not tested; bug case will fail
        );
    }
}

