contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // Ensure amount is strictly positive and not absurdly large
        vm.assume(amount > 0 && amount <= address(this).balance / 2);
        // Deploy a helper that reverts on receive
        Reverter reverter = new Reverter();
        address reverterAddr = address(reverter);
        // Fund the helper so it can deposit
        vm.deal(reverterAddr, amount);
        // Helper deposits into C
        vm.prank(reverterAddr);
        c.deposit{value: amount}();
        // Record the helper's credit before withdrawAll
        uint256 creditBefore = c.credit(reverterAddr);
        // The helper is an adversarial receiver; its receive will revert.
        // The reference withdrawAll must revert; the buggy one will not.
        bool reverted;
        vm.prank(reverterAddr);
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Reference: revert => credit unchanged (creditBefore > 0). Bug: no revert => credit zeroed, violating the invariant.
