pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user1, address user2) public {
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(user1 != address(0) && user2 != address(0));
        vm.assume(user1 != user2);
        vm.deal(user1, depositAmount + withdrawAmount);
        vm.deal(user2, depositAmount + withdrawAmount);

        // user1 deposits
        vm.prank(user1);
        c.deposit{value: depositAmount}();
        uint256 balanceAfterDeposit = c.balance();

        // user2 deposits
        vm.prank(user2);
        c.deposit{value: depositAmount}();

        // user1 withdraws
        vm.prank(user1);
        c.withdrawAll();

        // user2 withdraws
        vm.prank(user2);
        c.withdrawAll();

        // After both withdraw, the contract's Ether balance should be 0.
        // The mutant allows repeated withdrawals by the same user because credit is not reset.
        // So after the above sequence, the contract balance might be less than expected
        // (or an underflow error occurs in the mutant on second withdrawal of same user).
        // The invariant: contract Ether balance must be >= 0 and == balance variable.
        // But a simpler property: after both withdrawAll calls with fresh users,
        // the contract's Ether balance should be zero. The mutant breaks this if
        // user1 or user2 withdraw twice. We'll check that after two legitimate withdrawals,
        // the balance is zero if no reentrancy. Since user1 and user2 are distinct,
        // a correct contract ends with 0 Ether; a buggy one might allow user1 to withdraw again
        // because credit not reset, but here we only call once per user. That wouldn't expose the bug.
        // We need a property that the bug violates for SOME input. The correct invariant is:
        // the sum of all credit mappings + address(c).balance == c.balance().
        // The bug makes the credit mapping stale, so after withdrawal the sum diverges.
        // We'll assert that after each withdrawal, the caller's credit is 0.
        // But we need ONE assertion at the end. We'll compute:
        // uint256 totalCredit = c.credit(user1) + c.credit(user2);
        // assertEq(address(c).balance + totalCredit, c.balance());
        // This holds in correct version because balance = totalCredit + Ether balance.
        // In mutant, after withdrawal, credit(user) remains non-zero, so LHS > RHS, or if
        // someone else can drain, balance might underflow. But the statement says "withdrawAll"
        // state variable differs? Actually they said "state variable `withdrawAll`" which is a typo,
        // they meant value after call. We'll assert the invariant.
        uint256 totalCredit = c.credit(user1) + c.credit(user2);
        assertEq(address(c).balance + totalCredit, c.balance());
    }
}

