import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Restrict to valid EOA addresses (do not constrain beyond that)
        vm.assume(caller != address(0));

        // ensure caller has zero credit initially
        vm.startPrank(caller);
        (bool success, bytes memory ret) = address(c).call{value: 0}("");
        vm.stopPrank();
        require(success);

        // call withdrawAll as the caller
