        // first deposit and successful withdrawal
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();

        // second deposit to test if subsequent withdrawal is possible
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        bool ok;
        vm.prank(actor);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
